const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const forwarded = [];
  const service = new PaymentService(ledger, {
    async acknowledge(receipt) {
      forwarded.push(receipt);
      if (forwarded.length <= 2) throw new Transient('try again');
    }
  });
  const original = await service.pay('tenant', 'key', 100);
  assert.equal(forwarded.length, 3);
  assert.ok(forwarded.every(r => r === original));
  const concurrent = await Promise.all(Array.from({ length: 10 }, () => service.pay('tenant', 'key', 100)));
  assert.ok(concurrent.every(r => r === original));
  await assert.rejects(service.pay('tenant', 'key', 101), /^Error: key conflict$/);
  assert.equal(ledger.entries.length, 1);
  const other = await service.pay('other', 'key', 101);
  assert.notEqual(other, original);
  const direct = new Ledger();
  const results = await Promise.all(Array.from({ length: 10 }, () => direct.apply('a', 'b', 1)));
  assert.ok(results.every(r => r === results[0]));
  assert.equal(direct.entries.length, 1);
  await assert.rejects(direct.apply('a', 'b', 2), /key conflict/);

  for (const error of [new Transient('exhausted'), new Error('permanent')]) {
    let calls = 0;
    const l = new Ledger();
    const s = new PaymentService(l, { async acknowledge() { calls++; throw error; } });
    await assert.rejects(s.pay('a', 'b', 1, 5), e => e === error);
    assert.equal(calls, error instanceof Transient ? 5 : 1);
    assert.equal(l.entries.length, 1);
  }
  let actions = 0;
  const s = new PaymentService({ async apply() { actions++; } }, { async acknowledge() { actions++; } });
  for (const args of [['', 'k', 1], ['t', '', 1], ['t', 'k', 0], ['t', 'k', 1.5],
    ...[0, -1, 6, 1.5, NaN, Infinity].map(n => ['t', 'k', 1, n])]) {
    await assert.rejects(s.pay(...args), /^Error: invalid payment$/);
  }
  assert.equal(actions, 0);
  await assert.rejects(direct.apply('', 'b', 1), /invalid payment/);
  assert.equal(direct.entries.length, 1);
}
